UPDATE b_portal_list
SET gmt_modify = now()

    , type_id = #{typeId}


    , name = #{name}


    , gender = #{gender}


    , birthday = #{birthday}


    , passport = #{passport}


    , english_score = #{englishScore}


    , completion_date = #{completionDate}


    , visa_expiration_date = #{visaExpirationDate}


    , exam_results_date = #{examResultsDate}


    , student_visa_expiration_date = #{studentVisaExpirationDate}


    , has_completion_letter = #{hasCompletionLetter}


    , json_str = #{jsonStr}


    , contract_str = #{contractStr}


    , adviser_id = #{adviserId}


    , official_id = #{officialId}


    , mara_id = #{maraId}


    , service_order_id = #{serviceOrderId}


    , str_state = #{strState}

WHERE id = #{id};

UPDATE b_portal_list
SET gmt_modify = now(),
    ai_consult_content = #{aiConsultContent}
WHERE id = #{id};

mapper.select:
SELECT id, gmt_create AS gmtCreate, gmt_modify AS gmtModify, type_id AS typeId, name, gender, birthday, passport, english_score AS englishScore, completion_date AS completionDate, visa_expiration_date AS visaExpirationDate, exam_results_date AS examResultsDate, student_visa_expiration_date AS studentVisaExpirationDate, has_completion_letter AS hasCompletionLetter, json_str AS jsonStr, contract_str AS contractStr, ai_consult_content AS aiConsultContent, adviser_id AS adviserId, official_id AS officialId, mara_id AS maraId, service_order_id AS serviceOrderId, str_state AS strState FROM b_portal_list WHERE 1 = 1
AND type_id = #{typeId}
AND str_state = #{strState}
AND name LIKE '%${keyword}%'
AND adviser_id = #{adviserId}
AND adviser_id IN ( SELECT id FROM tb_adviser WHERE region_id IN ( SELECT id FROM tb_region WHERE id = #{adviserRegionId} OR parent_id = #{adviserRegionId} ) )
AND official_id = #{officialId}
AND official_id IN ( SELECT id FROM b_official WHERE region_id IN ( SELECT id FROM tb_region WHERE id = #{officialRegionId} OR parent_id = #{officialRegionId} ) )
AND mara_id = #{maraId}
ORDER BY id DESC LIMIT #{offset}, #{rows};

SELECT count(*)
FROM b_portal_list
WHERE 1 = 1

    AND type_id = #{typeId}



    AND str_state = #{strState}


    AND name LIKE '%${keyword}%'


    AND adviser_id = #{adviserId}


    AND adviser_id IN (
        SELECT id FROM tb_adviser WHERE region_id IN (
            SELECT id FROM tb_region WHERE id = #{adviserRegionId} OR parent_id = #{adviserRegionId}
        )
    )


    AND official_id = #{officialId}


    AND official_id IN (
        SELECT id FROM b_official WHERE region_id IN (
            SELECT id FROM tb_region WHERE id = #{officialRegionId} OR parent_id = #{officialRegionId}
        )
    )


    AND mara_id = #{maraId}

;

SELECT id, gmt_create AS gmtCreate, gmt_modify AS gmtModify, type_id AS typeId, name, gender, birthday, passport, english_score AS englishScore, completion_date AS completionDate, visa_expiration_date AS visaExpirationDate, exam_results_date AS examResultsDate, student_visa_expiration_date AS studentVisaExpirationDate, has_completion_letter AS hasCompletionLetter, json_str AS jsonStr, contract_str AS contractStr, ai_consult_content AS aiConsultContent, adviser_id AS adviserId, official_id AS officialId, mara_id AS maraId, service_order_id AS serviceOrderId, str_state AS strState FROM b_portal_list WHERE id = #{id, jdbcType=INTEGER}
AND adviser_id = #{adviserId}
AND adviser_id IN ( SELECT id FROM tb_adviser WHERE region_id IN ( SELECT id FROM tb_region WHERE id = #{adviserRegionId} OR parent_id = #{adviserRegionId} ) )
AND official_id = #{officialId}
AND official_id IN ( SELECT id FROM b_official WHERE region_id IN ( SELECT id FROM tb_region WHERE id = #{officialRegionId} OR parent_id = #{officialRegionId} ) )
AND mara_id = #{maraId}
;
